import React, { useState } from 'react';
import api from '../api';

function AdminChecklistView({ checklist, allTemplates, onBack, onUpdate }) {
  const [showTaskForm, setShowTaskForm] = useState(false);
  const [taskFormData, setTaskFormData] = useState({
    title: '',
    description: ''
  });

  // Get tasks that belong to this checklist
  const checklistTasks = allTemplates.filter(t => t.checklist_id === checklist.id);

  const handleCreateTask = async (e) => {
    e.preventDefault();
    try {
      await api.createTemplate({
        ...taskFormData,
        frequency: checklist.frequency,
        checklist_id: checklist.id
      });
      setTaskFormData({ title: '', description: '' });
      setShowTaskForm(false);
      onUpdate();
    } catch (error) {
      console.error('Error creating task:', error);
    }
  };

  const handleDeleteTask = async (task) => {
    if (window.confirm(`Are you sure you want to delete "${task.title}"? This will permanently remove the task and cannot be undone.`)) {
      try {
        await api.deleteTemplate(task.id);
        onUpdate();
      } catch (error) {
        console.error('Error deleting task:', error);
      }
    }
  };

  const handleDeleteChecklist = async () => {
    if (window.confirm(`Are you sure you want to delete the entire "${checklist.name}" checklist? This will permanently delete the checklist and ALL ${checklistTasks.length} tasks inside it. This cannot be undone.`)) {
      try {
        await api.deleteChecklist(checklist.id);
        onBack(); // Go back to templates page after deletion
      } catch (error) {
        console.error('Error deleting checklist:', error);
      }
    }
  };

  return (
    <div className="main-content">
      <div className="page-header">
        <button 
          className="btn btn-secondary" 
          onClick={onBack}
          style={{ marginBottom: '15px' }}
        >
          ← Back to Templates
        </button>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start' }}>
          <div>
            <h1>{checklist.name}</h1>
            <p>{checklist.description}</p>
            <div style={{ marginTop: '10px' }}>
              <span style={{ color: '#7f8c8d' }}>
                Frequency: {checklist.frequency}
              </span>
            </div>
          </div>
          <button
            className="btn"
            onClick={handleDeleteChecklist}
            style={{ backgroundColor: '#e74c3c', color: 'white' }}
            onMouseEnter={(e) => e.target.style.backgroundColor = '#c0392b'}
            onMouseLeave={(e) => e.target.style.backgroundColor = '#e74c3c'}
          >
            🗑️ Delete Checklist
          </button>
        </div>
      </div>

      <button 
        className="btn btn-primary" 
        onClick={() => setShowTaskForm(!showTaskForm)}
        style={{ marginBottom: '20px' }}
      >
        {showTaskForm ? 'Cancel' : '+ Add Task to Checklist'}
      </button>

      {/* Add Task Form */}
      {showTaskForm && (
        <div className="task-section" style={{ marginBottom: '30px' }}>
          <h3 style={{ marginBottom: '20px' }}>Add New Task</h3>
          <form onSubmit={handleCreateTask}>
            <div className="form-group">
              <label>Task Title</label>
              <input
                type="text"
                className="form-control"
                value={taskFormData.title}
                onChange={(e) => setTaskFormData({ ...taskFormData, title: e.target.value })}
                required
                placeholder="e.g., Check inventory levels"
              />
            </div>
            <div className="form-group">
              <label>Description</label>
              <textarea
                className="form-control"
                value={taskFormData.description}
                onChange={(e) => setTaskFormData({ ...taskFormData, description: e.target.value })}
                placeholder="Optional description"
              />
            </div>
            <button type="submit" className="btn btn-primary">
              Add Task
            </button>
          </form>
        </div>
      )}

      {/* Tasks in this Checklist */}
      <div className="task-section">
        <div className="section-header">
          <h2>Tasks in this Checklist</h2>
          <span style={{ fontSize: '14px', color: '#7f8c8d' }}>
            {checklistTasks.length} task{checklistTasks.length !== 1 ? 's' : ''}
          </span>
        </div>

        {checklistTasks.length === 0 ? (
          <p style={{ color: '#7f8c8d', textAlign: 'center', padding: '40px' }}>
            No tasks in this checklist yet. Click "+ Add Task to Checklist" to create one.
          </p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
            {checklistTasks.map(task => (
              <div
                key={task.id}
                style={{
                  border: '1px solid #e0e0e0',
                  borderRadius: '6px',
                  padding: '15px',
                  backgroundColor: 'white'
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start' }}>
                  <div style={{ flex: 1 }}>
                    <h4 style={{ marginBottom: '5px', color: '#2c3e50' }}>{task.title}</h4>
                    {task.description && (
                      <p style={{ color: '#7f8c8d', fontSize: '14px', marginBottom: '10px' }}>
                        {task.description}
                      </p>
                    )}
                  </div>
                  <button
                    className="btn"
                    onClick={() => handleDeleteTask(task)}
                    style={{ backgroundColor: '#e74c3c', color: 'white' }}
                    onMouseEnter={(e) => e.target.style.backgroundColor = '#c0392b'}
                    onMouseLeave={(e) => e.target.style.backgroundColor = '#e74c3c'}
                  >
                    🗑️ Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default AdminChecklistView;
